using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.Serialization;using System.Xml.Linq;using V15Voice;
[DataContract]public sealed class RenoAudit{[DataMember]public List<RenoCase> cases;}
[DataContract]public sealed class RenoCase{[DataMember]public string name;[DataMember]public List<RenoCue> cues;[DataMember]public List<RenoStage> file_stages,auto_stages;}
[DataContract]public sealed class RenoCue{[DataMember]public int id;[DataMember]public double start,end;[DataMember]public string text;}
[DataContract]public sealed class RenoStage{[DataMember]public int number;[DataMember]public List<int> ids;[DataMember]public RenoMeasure measure;[DataMember]public List<RenoAttempt> attempts;}
[DataContract]public sealed class RenoMeasure{[DataMember]public double tts,pauses,breaths,natural,after,target,delta,speed;}
[DataContract]public sealed class RenoAttempt{[DataMember]public int number;[DataMember]public string strategy,code,model_verdict;[DataMember]public List<AiCueText> cues;[DataMember]public RenoMeasure measure;}
public static class Reno300Tests {
 static int count;static string root;static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}
 static Wave Tone(double s){return new Wave{Rate=24000,Samples=Enumerable.Range(0,(int)Math.Round(s*24000)).Select(i=>(short)(5000*Math.Cos(i*.061))).ToArray()};}
 static VoiceSettings Settings(){return new VoiceSettings{Mode=2,AiMode=2,WorkflowMode=2,Key="K:3",Breathing=(int)BreathMode.None,Normalize=false,Slow=false,GentleFit=false,Punctuation=0,Gap=0,MinSpeed=.9,MaxSpeed=1.25};}
 static List<Cue> Cues(RenoCase c){return c.cues.Select(x=>new Cue{Id=x.id,Start=x.start,End=x.end,Text=x.text}).ToList();}
 static AiMeasurement Recorded(RenoMeasure d,string folder){if(d==null)return null;var m=new AiMeasurement{Tts=d.tts,AppPauses=d.pauses,Breaths=d.breaths,Natural=d.natural,After=d.after,Target=d.target,Speed=d.speed,Fits=Math.Abs(d.delta)<.021,NeedsRepair=Math.Abs(d.delta)>=.021,Kind=d.delta<-.021?"UNDER DURATION":d.delta>.021?"OVER DURATION":"NONE",Detail="RECORDED 2.0.17 measurement replay; fixture PCM, not new Steven voice",PauseNote="Replay: keep original measured pause decision",DeviceInfo="RECORDED GPU evidence from report; not GPU execution in this test"};m.Audio=Path.Combine(folder,Guid.NewGuid()+".wav");m.NaturalAudio=Path.Combine(folder,Guid.NewGuid()+".wav");Tone(m.After).Write(m.Audio);Tone(m.Natural).Write(m.NaturalAudio);m.Hash=StateFiles.Hash(m.Audio);m.NaturalHash=StateFiles.Hash(m.NaturalAudio);return m;}
 static AiRepairSession Replay(RenoCase c,string suffix,bool auto){string folder=Path.Combine(root,c.name+suffix);Directory.CreateDirectory(folder);string source=Path.Combine(folder,"story.srt");var cues=Cues(c);File.WriteAllText(source,Scripts.ToSrt(cues));cues=Scripts.ParseSrt(File.ReadAllText(source));var p=AiRepairSession.Open(source,cues,folder,Settings(),true,"reno-replay");foreach(var s in auto?c.auto_stages:c.file_stages){var r=p.Rows.Single(x=>x.Stage.Number==s.number);r.Original=Recorded(s.measure,p.Folder);}p.Save();return p;}
 sealed class Voice:KokoroEngine {
  public static readonly Dictionary<string,double> Seconds=new Dictionary<string,double>();public static readonly List<string> Requests=new List<string>();public static bool Fail;
  public override void CheckFiles(){}public override Wave Generate(string text,double speed,string path){Requests.Add(text);if(Fail)throw new IOException("candidate fixture engine failure");if(!Seconds.ContainsKey(text))throw new IOException("Unexpected TTS: "+text);return Tone(Seconds[text]/speed);}
 }
 static KokoroEngine Engine(string role){return new Voice{Root=root,VoiceName="Reno300 fixture "+role,DeviceMode="cpu"};}
 sealed class Writer:ITextRewriter {public int Calls;public bool Repeat;public string Response;public string Rewrite(string prompt,Func<bool> cancel,Action<string> activity){Calls++;if(Repeat){int at=prompt.IndexOf("\nCues: ")+7,end=prompt.IndexOf("\nAvoid previous",at);return prompt.Substring(at,end-at);}return Response;}}
 sealed class Translator:ITextRewriter {public int Calls;public string Rewrite(string prompt,Func<bool> cancel,Action<string> activity){Calls++;if(prompt.StartsWith("TASK=TRANSLATION_VERIFY"))return "{\"items\":[{\"id\":5,\"ok\":true,\"source_subject_type\":\"person\",\"target_subject_type\":\"person\",\"reason\":\"supplied fixture translation\"},{\"id\":7,\"ok\":true,\"source_subject_type\":\"person\",\"target_subject_type\":\"person\",\"reason\":\"supplied fixture translation\"}]}";return "{\"cues\":[{\"id\":5,\"text\":\"Ông ấy chắc rằng chúng tôi sẽ làm hỏng sàn nhà và cầu xin giúp đỡ.\"},{\"id\":7,\"text\":\"Chúng tôi đã tiêu hết tiền tiết kiệm cho ngôi nhà cũ trên núi này.\"}]}";}}
 static string Json(IEnumerable<Cue> cues){return LocalAi.Json(new AiRewriteText{cues=cues.Select(c=>new AiCueText{id=c.Id,text=c.Text}).ToList()});}
