  foreach(var pair in new[]{new[]{"He was sure we'd ruin the floor and beg for help.","He was sure we would ruin the floor and beg for help."},new[]{"We'd already spent our savings on this old mountain home.","We had already spent our savings on this old mountain home."},new[]{"Both our arms felt completely useless.","Both of our arms felt completely useless."},new[]{"He looked unimpressed by all that noise.","He looked unimpressed by all of that noise."},new[]{"I joked that we might need another nine coats of paint.","I joked that we might be in need of another nine coats of paint."},new[]{"There was no good reason to risk our fingers doing that.","There was no good reason to put our fingers at risk doing that."},new[]{"We knew it could become the room's best feature.","We knew that it could become the best feature of the room."},new[]{"The next problem was much harder to avoid.","The next problem was much more difficult to avoid."}}){var a=new List<Cue>{new Cue{Id=1,Start=0,End=3,Text=pair[0]}};var b=VoiceRenderReport.Snapshot(a);b[0].Text=pair[1];Check(RepairPolicy.Check(a,b).Safe,"Admit grounded equivalent: "+pair[1]);}
