  Check(File.ReadAllText(result.Bundle.Changes).Contains("EN ĐÃ DÙNG: He was sure we would ruin")&&File.ReadAllText(result.Bundle.Changes).Contains("VI ĐỐI CHIẾU: Ông ấy")&&WorkflowReports.Changed(options,result.Cues).All(c=>options.Translation.Text.ContainsKey(c.Id)),"Only actually applied cues appear with real supplied fixture Vietnamese translations in the quick report");
  int requests=Voice.Requests.Count;using(var e=Engine("A")){var retry=Options(session,2);retry.Translator=tr;retry.Translation=options.Translation;retry.ReportContext.SourceCues=session.Effective();Renderer.Render(session.Effective(),e,retry,Path.Combine(job,"cached.wav"),(n,m)=>{});Check(Voice.Requests.Count==requests,"Re-render reuses verified per-stage PCM without synthesizing successful stages again");Check(retry.RunReport.Stages.Where(s=>s.AppPauses.HasValue).All(s=>!s.InnerPauses.HasValue&&!s.BetweenPauses.HasValue),"Cached stages do not manufacture pause-component splits");}
